/**
 * 掃除（動きは変わらない）: generate_reply の FEEDBACK-*-gr（p7）と WEEKLY（p6）は v2 の並び（p8 以上・振り分けは入れない）で
 * 返信生成・最終チェック・会話を合わせるのどれにも届かず、ブレインも generate_reply を読まない。週の整理（rule-organize）が毎週読む分だけ費用がかかる。
 * 6巡目の SQL の ④（任意）と同じ。SQL は条件で選ぶ（ここに id は並べない）。
 */
export const R9_SWEEP_WHERE = "is_active AND action_type = 'generate_reply' AND NOT is_permanent AND ((rule_key LIKE 'FEEDBACK-%-gr' AND priority < 8) OR (rule_key LIKE 'WEEKLY-%' AND priority < 8))";

